cat > test/money.test.js << 'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('RATES exports correct conversion rates', () => {
  assert.deepEqual(RATES, { EUR: 1, USD: 1.085, GBP: 0.8425 });
});

test('convert EUR to USD', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 108);
});

test('convert EUR to GBP', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 84);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100);
});

test('convert returns error for unknown currency', () => {
  const result = convert(100, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert handles large amounts', () => {
  const result = convert(123456, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 133950);
});

test('convert handles zero', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert handles negative amounts', () => {
  const result = convert(-100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -108);
});

test('convert applies rounding correctly', () => {
  const result = convert(123, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 133);
});

test('convert USD to EUR', () => {
  const result = convert(108, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value <= 100, true);
});

test('convert GBP to EUR', () => {
  const result = convert(84, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value <= 100, true);
});

test('formatMoney EUR', () => {
  const result = formatMoney(123456, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, '€1,234.56');
});

test('formatMoney USD', () => {
  const result = formatMoney(100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, '$1.08');
});

test('formatMoney GBP', () => {
  const result = formatMoney(100, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, '£0.84');
});

test('formatMoney uses correct currency symbol', () => {
  const eur = formatMoney(100, 'EUR');
  const usd = formatMoney(100, 'USD');
  const gbp = formatMoney(100, 'GBP');
  assert.equal(eur.value.includes('€'), true);
  assert.equal(usd.value.includes('$'), true);
  assert.equal(gbp.value.includes('£'), true);
});

test('formatMoney with thousands separator', () => {
  const result = formatMoney(1234567, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, '€12,345.67');
});

test('formatMoney with thousands separator USD', () => {
  const result = formatMoney(1000000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value.includes(','), true);
});

test('formatMoney with zero', () => {
  const result = formatMoney(0, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, '€0.00');
});

test('formatMoney with negative amount', () => {
  const result = formatMoney(-100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, '-€1.00');
});

test('formatMoney with negative amount USD', () => {
  const result = formatMoney(-100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value.startsWith('-'), true);
});

test('formatMoney returns error for unknown currency', () => {
  const result = formatMoney(100, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('formatMoney with cents only', () => {
  const result = formatMoney(50, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, '€0.50');
});

test('formatMoney with small USD amount', () => {
  const result = formatMoney(10, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, '$0.10');
});

test('formatMoney with large amounts uses thousands separator', () => {
  const result = formatMoney(9999999, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value.includes(','), true);
});

test('convert result is integer', () => {
  const result = convert(123, 'USD');
  assert.equal(Number.isInteger(result.value), true);
});

test('formatMoney uses thousands separator correctly', () => {
  const result = formatMoney(100000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, '€1,000.00');
});

test('formatMoney with 999999 cents', () => {
  const result = formatMoney(999999, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, '€9,999.99');
});

test('convert EUR rate is 1', () => {
  const result = convert(555, 'EUR');
  assert.equal(result.value, 555);
});

test('formatMoney preserves precision through conversion', () => {
  const converted = convert(123456, 'USD');
  assert.equal(converted.ok, true);
  const formatted = formatMoney(123456, 'USD');
  assert.equal(formatted.ok, true);
});

test('convert handles fractional results with rounding', () => {
  const result = convert(1, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(typeof result.value, 'number');
});

test('formatMoney large negative amount', () => {
  const result = formatMoney(-123456, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value.startsWith('-'), true);
  assert.equal(result.value.includes('$'), true);
});

test('convert with null currency returns error', () => {
  const result = convert(100, null);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('formatMoney with empty string currency returns error', () => {
  const result = formatMoney(100, '');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert case sensitive currency', () => {
  const result1 = convert(100, 'usd');
  const result2 = convert(100, 'USD');
  assert.equal(result1.ok, false);
  assert.equal(result2.ok, true);
});

test('formatMoney case sensitive currency', () => {
  const result1 = formatMoney(100, 'eur');
  const result2 = formatMoney(100, 'EUR');
  assert.equal(result1.ok, false);
  assert.equal(result2.ok, true);
});

test('convert precision: USD rate', () => {
  const result = convert(100, 'USD');
  assert.equal(result.value, 108);
});

test('convert precision: GBP rate', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.value, 84);
});

test('formatMoney decimal point always present', () => {
  const result = formatMoney(100, 'EUR');
  assert.equal(result.value.includes('.'), true);
});

test('formatMoney two decimal places', () => {
  const result = formatMoney(100, 'EUR');
  const parts = result.value.split('.');
  assert.equal(parts[1], '00');
});

test('convert returns ok structure', () => {
  const result = convert(100, 'USD');
  assert.equal('ok' in result, true);
  assert.equal('value' in result, true);
  assert.equal(result.ok, true);
});

test('formatMoney returns ok structure', () => {
  const result = formatMoney(100, 'USD');
  assert.equal('ok' in result, true);
  assert.equal('value' in result, true);
  assert.equal(result.ok, true);
});

test('formatMoney returns error structure on failure', () => {
  const result = formatMoney(100, 'XXX');
  assert.equal('ok' in result, true);
  assert.equal('error' in result, true);
  assert.equal(result.ok, false);
});
EOF

